mapper.select:
WITH scored AS MATERIALIZED (
    SELECT c.*, c.embedding <=> CAST(#{vector} AS vector) AS distance
    FROM knowledge_chunk c
    WHERE c.dataset_version = #{version} AND c.embedding IS NOT NULL

        AND c.kind IN #{v}


        AND c.subject IN #{v}


        AND c.thinking_type IN #{v}


        AND (c.kind IN ('SUBJECT_GUIDE', 'THINKING_TYPE') OR c.grades &&
        ARRAY[#{v}]::smallint[])


        AND (c.kind IN ('SUBJECT_GUIDE', 'THINKING_TYPE') OR c.semesters &&
        ARRAY[#{v}]::varchar[])

)
SELECT , greatest(0.0, least(1.0, 1.0 - c.distance)) AS similarity
FROM scored c
WHERE c.distance BETWEEN -0.000001 AND 2.000001
  AND greatest(0.0, least(1.0, 1.0 - c.distance)) >= #{minimum}
ORDER BY similarity DESC, c.kind, c.id LIMIT #{k}
